public class SuperCallTimer {
    @RuntimeType
    public Object intercept(@Origin Method m, @SuperCall Callable<?> original) throws Exception {
        long t0 = System.nanoTime();
        try {
            return original.call();          // the original body, on this same object
        } finally {
            System.out.println(m.getName() + " took " + (System.nanoTime() - t0) + " ns");
        }
    }
}

// the service class is open by default in Java; final methods would be skipped
FxQuoteService timed = new ByteBuddy()
        .subclass(FxQuoteService.class)
        .method(isPublic().and(isDeclaredBy(FxQuoteService.class)))
        .intercept(MethodDelegation.withDefaultConfiguration()
                .filter(named("intercept")).to(new SuperCallTimer()))
        .make().load(FxQuoteService.class.getClassLoader()).getLoaded()
        .getDeclaredConstructor().newInstance();

