// 1. the proxy IS the object: self-calls intercepted, final methods run on real state
public class InSubclass {
    @RuntimeType
    public Object intercept(@Origin Method m, @SuperCall Callable<?> original) throws Exception {
        return original.call();
    }
}

// 2. the proxy forwards: self-calls skip it, final methods run on the proxy's own fields
public class Forwarding {
    private final Object target;
    public Forwarding(Object target) { this.target = target; }

    @RuntimeType
    public Object intercept(@Origin Method m, @AllArguments Object[] args) throws Throwable {
        try {
            return m.invoke(target, args);
        } catch (InvocationTargetException e) {
            throw e.getCause();
        }
    }
}

